from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the solid separator column.
    sep = min(
        range(w),
        key=lambda c: len(set(grid[r][c] for r in range(h)))
    )
    left_w = sep
    right_w = w - sep - 1
    width = min(left_w, right_w)

    left = [row[:left_w] for row in grid]
    right = [row[sep + 1:sep + 1 + width] for row in grid]

    def background(panel):
        return Counter(v for row in panel for v in row).most_common(1)[0][0]

    lb, rb = background(left), background(right)
    lcolors = {v for row in left for v in row if v != lb}
    rcolors = {v for row in right for v in row if v != rb}
    common = lcolors & rcolors

    def signal(panel, bg, candidates):
        if candidates:
            # Prefer the shared foreground color when both halves contain it.
            color = min(candidates, key=lambda v: sum(x == v for row in panel for x in row))
        else:
            color = bg
        return [[x == color for x in row[:width]] for row in panel]

    ls = signal(left, lb, common if common else lcolors)
    rs = signal(right, rb, common if common else rcolors)

    return [
        [3 if ls[r][c] and rs[r][c] else 4 for c in range(width)]
        for r in range(h)
    ]
